  "type": "module",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test",
    "build": "tsc --noEmit"
  },
  "license": "MIT",
  "homepage": "https://adtention.ai",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/adtention-ai/opencode.git"
  },
  "bugs": {
    "url": "https://github.com/adtention-ai/opencode/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "exports": {
